// Authored extension, generated by build-data.mjs. Bottom-first rows; preserve the atlas/bench geometry.
export const RELAY_STAGE_ID = 'local_relay_lab';
export const RELAY_NORMAL = ['Err#rqirS', '##rrr#h##', '#hvhqhh##', '##hhrrrrS'];
export const RELAY_BOSS_LEFT = ['Err#rqir', '##rrrrrr', '#hhhqvrr', '##hhrrrr'];

export function finishRelayStage(files, pathOf) {
  const base = files.stages.act1autochess_m02;
  if (!base) throw new Error('Relay stage requires act1autochess_m02');
  const stage = structuredClone(base);
  Object.assign(stage, { id: RELAY_STAGE_ID, name: '中继试验场·双廊', active: true, weight: 0,
    manualOnly: true, modes: Object.keys(files.config.modes), devices: [], mapChars: [], runes: [], globalBuffs: [] });
  const tile = (tileKey, height, buildable, passable, special = null) => ({
    tileKey, height, buildable, passable, groundPassable: passable === 'ALL', flyPassable: passable !== 'NONE', special, bb: {},
  });
  stage.tiles.h = tile('tile_wall', 'HIGH', 'RANGED', 'FLY');
  stage.tiles.i = tile('tile_infection', 'LOW', 'ALL', 'ALL', 'infection');
  stage.tiles.v = tile('tile_infection', 'HIGH', 'RANGED', 'FLY', 'infection');
  stage.tiles.q = tile('tile_healing', 'LOW', 'ALL', 'ALL', 'healing');
  stage.special = { infection: { bb: { damage: 80, atk: 0.3, attack_speed: 30, duration: 300 } }, healing: { maxHpRatio: 0.03 } };
  for (let i = 0; i < 4; i++) {
    // 联防: the second normal board connects to the first at col 10, as on the original atlas.
    stage.rows[9 + i] = '##' + RELAY_NORMAL[i] + RELAY_NORMAL[i].slice(1) + '##';
    stage.rows[2 + i] = '##' + RELAY_BOSS_LEFT[i] + (i === 0 || i === 3 ? 'O' : 'f')
      + [...RELAY_BOSS_LEFT[i]].reverse().join('') + '##';
  }
  // Row 1 retains the original portals at (1,3)/(1,17) and boss bench pads.
  const deployIn = (r0, r1, c0, c1) => {
    const melee = [], rangedOnly = [];
    for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
      const t = stage.tiles[stage.rows[r][c]];
      if (t?.buildable === 'NONE' || !t) continue;
      if (t.height === 'LOW' && ['ALL', 'MELEE'].includes(t.buildable)) melee.push([r, c]);
      else if (t.buildable === 'RANGED' || (t.height === 'HIGH' && t.buildable === 'ALL')) rangedOnly.push([r, c]);
    }
    return { melee, rangedOnly, changedByDevices: [] };
  };
  stage.deployTiles = { normal: deployIn(9, 12, 2, 10), bossLeft: deployIn(1, 5, 2, 10), bossRight: deployIn(1, 5, 10, 18) };
  stage.groundPaths = {};
  for (const key of Object.keys(base.groundPaths)) {
    const [start, end] = key.split('->').map(p => p.split(',').map(Number));
    const path = pathOf({ rows: stage.rows, legend: stage.tiles }, [], start, end);
    if (path) stage.groundPaths[key] = path;
  }
  stage.groundPathsWithDevices = structuredClone(stage.groundPaths);
  files.stages[stage.id] = stage;
}
